/* Ширина = 100% минус 40px отступов */
.container {
  width: calc(100% - 40px);
  padding: 20px;
}

/* Комбинируем rem и px */
.element {
  font-size: calc(1rem + 2px);
}

/* Центрирование с учётом ширины */
.centered {
  width: 300px;
  margin-left: calc(50% - 150px);
}

/* Ширина: 100%, но не шире 600px */
.container {
  width: min(100%, 600px);
}

/* Ширина: 100%, но не уже 300px */
.container {
  width: max(100%, 300px);
}

/* Шрифт: мин 16px, preferred 2vw, макс 24px */
h1 {
  font-size: clamp(16px, 2vw, 24px);
}

/* Ширина: мин 300px, preferred 80%, макс 1200px */
.container {
  width: clamp(300px, 80%, 1200px);
}

/* Padding: мин 1rem, preferred 5vw, макс 3rem */
.section {
  padding: clamp(1rem, 5vw, 3rem);
}

/* Объявление переменных */
:root {
  --primary: #0066cc;
  --spacing: 16px;
  --radius: 8px;
}

/* Использование */
.btn {
  background: var(--primary);
  padding: var(--spacing);
  border-radius: var(--radius);
}

/* Значение по умолчанию */
.element {
  color: var(--text-color, #333);
}

.tooltip::after {
  content: attr(data-label);
  position: absolute;
  background: black;
  color: white;
  padding: 4px 8px;
  border-radius: 4px;
}

.hero {
  background: url('/images/hero.jpg') center/cover no-repeat;
}

@font-face {
  font-family: 'CustomFont';
  src: url('/fonts/custom.woff2') format('woff2');
}

/* Линейный градиент */
.gradient {
  background: linear-gradient(to right, #667eea, #764ba2);
}

/* Радиальный градиент */
.gradient {
  background: radial-gradient(circle, #667eea, #764ba2);
}

/* Градиент как фон кнопки */
.btn {
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
}

h1 {
  font-size: clamp(1.5rem, 4vw, 3rem);
  line-height: 1.2;
}

p {
  font-size: clamp(1rem, 2vw, 1.25rem);
  line-height: 1.6;
}

.container {
  width: min(100% - 2rem, 1200px);
  margin: 0 auto;
  padding: clamp(1rem, 3vw, 2rem);
}

:root {
  --bg: white;
  --text: #333;
  --border: #ddd;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #1a1a2e;
    --text: #e0e0e0;
    --border: #333;
  }
}

body {
  background: var(--bg);
  color: var(--text);
}

.card {
  border: 1px solid var(--border);
}
